"use client";

import { forwardRef, useMemo } from "react";
import DOMPurify from "dompurify";

/**
 * Props for {@link SafeSvg}.
 */
export interface SafeSvgProps {
  /** Raw SVG markup generated by client diagram renderers (always sanitized with DOMPurify). */
  svg: string;
  /** Optional CSS classes for the wrapper container. */
  className?: string;
}

/**
 * Audited client boundary for rendering SVG diagrams sanitized via DOMPurify.
 */
export const SafeSvg = forwardRef<HTMLDivElement, SafeSvgProps>(function SafeSvg({ svg, className }, ref) {
  const cleanSvg = useMemo(
    () =>
      typeof window === "undefined"
        ? ""
        : DOMPurify.sanitize(svg, {
            USE_PROFILES: { svg: true, svgFilters: true, html: true },
            FORBID_TAGS: ["script"],
            FORBID_ATTR: ["onload", "onerror", "onclick"],
          }),
    [svg]
  );

  return <div ref={ref} className={className} dangerouslySetInnerHTML={{ __html: cleanSvg }} />;
});
